      blurb: L('Un llop que només vol fer sopa de verdures!', '¡Un lobo que solo quiere hacer sopa de verduras!', 'A wolf who only wants to make vegetable soup!'),
      cast: [
        { id: 'n', e: '📻', fx: 'normal', color: '#3a3a5c', name: L('Narradora', 'Narradora', 'Narrator') },
        { id: 'wolf', e: '🐺', fx: 'robotFast', color: '#6c757d', name: L('El llop', 'El lobo', 'The wolf') },
        { id: 'girl', e: '👧', fx: 'squeak', color: '#e5383b', name: L('La Caputxeta', 'Caperucita', 'Little Red') },
        { id: 'gran', e: '👵', fx: 'robot', color: '#9b5de5', name: L("L'àvia", 'La abuela', 'Grandma') },
        { id: 'bird', e: '🐦', fx: 'squeakHi', color: '#3a86ff', name: L("L'ocellet", 'El pajarito', 'The little bird') },
      ],
      lines: [
        l('n', 'Hi havia una vegada un bosc molt verd, amb un llop molt especial.', 'Había una vez un bosque muy verde, con un lobo muy especial.', 'Once upon a time there was a green forest with a very special wolf.'),
        l('wolf', 'Hola! Sóc el llop. I no em vull menjar ningú!', '¡Hola! Soy el lobo. ¡Y no me quiero comer a nadie!', "Hello! I'm the wolf. And I don't want to eat anybody!"),
        l('n', 'El llop tenia un somni: ser cuiner. Però un cuiner de verdures!', 'El lobo tenía un sueño: ser cocinero. ¡Pero un cocinero de verduras!', 'The wolf had a dream: to be a chef. A vegetable chef!'),
        l('wolf', 'Bròquil, pastanagues, carbassons... Mmm, quina olor més bona!', 'Brócoli, zanahorias, calabacines... ¡Mmm, qué olor tan rico!', 'Broccoli, carrots, courgettes... Mmm, what a lovely smell!'),
        l('n', 'Un dia, la Caputxeta passava pel bosc amb una cistella.', 'Un día, Caperucita pasaba por el bosque con una cesta.', 'One day, Little Red was walking through the forest with a basket.'),
        l('girl', "Tralarà, tralarí! Porto pastissos a l'àvia!", '¡Tralará, tralarí! ¡Llevo pasteles a la abuela!', "Tra-la-la, tra-la-lee! I'm taking cakes to Grandma!"),
        l('bird', 'Piu, piu! Compte, Caputxeta! Hi ha un llop!', '¡Pío, pío! ¡Cuidado, Caperucita! ¡Hay un lobo!', 'Tweet, tweet! Watch out, Little Red! There is a wolf!', 'whoosh'),
        l('girl', 'Un llop?! Ai, ai, ai! Quina por!', '¿¡Un lobo!? ¡Ay, ay, ay! ¡Qué miedo!', 'A wolf?! Oh no, oh no! How scary!'),
        l('wolf', 'No, no, espera! Només et volia preguntar una cosa.', '¡No, no, espera! Solo te quería preguntar una cosa.', 'No, no, wait! I just wanted to ask you something.'),
        l('girl', 'Una cosa? Quina cosa?', '¿Una cosa? ¿Qué cosa?', 'Something? What is it?'),
        l('wolf', 'Saps cuinar sopa de carbassa? És la meva preferida!', '¿Sabes cocinar sopa de calabaza? ¡Es mi favorita!', 'Can you cook pumpkin soup? It is my favourite!'),
        l('n', 'La Caputxeta es va quedar parada. Un llop que vol sopa?', 'Caperucita se quedó parada. ¿Un lobo que quiere sopa?', 'Little Red stood still. A wolf who wants soup?'),
        l('girl', 'Doncs... la meva àvia fa la millor sopa del món!', 'Pues... ¡mi abuela hace la mejor sopa del mundo!', 'Well... my grandma makes the best soup in the world!'),
        l('wolf', 'De debò? Em portes a casa seva, si us plau?', '¿De verdad? ¿Me llevas a su casa, por favor?', 'Really? Will you take me to her house, please?'),
        l('bird', 'Piu, piu! Això és una trampa! Segur que és una trampa!', '¡Pío, pío! ¡Esto es una trampa! ¡Seguro que es una trampa!', "Tweet, tweet! It's a trap! I'm sure it's a trap!"),
        l('girl', 'Tranquil, ocellet. Aquest llop sembla molt educat.', 'Tranquilo, pajarito. Este lobo parece muy educado.', 'Calm down, little bird. This wolf seems very polite.'),
        l('n', "I així, tots tres van anar cap a casa de l'àvia.", 'Y así, los tres fueron hacia la casa de la abuela.', "And so, the three of them went to Grandma's house."),
        l('n', 'Toc, toc, toc!', '¡Toc, toc, toc!', 'Knock, knock, knock!', 'knock'),
        l('gran', 'Qui hi ha? Si és el llop, no hi sóc!', '¿Quién es? ¡Si es el lobo, no estoy!', "Who is it? If it's the wolf, I'm not home!"),
        l('girl', 'Àvia, sóc jo! I porto un llop que vol aprendre a cuinar.', '¡Abuela, soy yo! Y traigo un lobo que quiere aprender a cocinar.', "Grandma, it's me! And I've brought a wolf who wants to learn to cook."),
        l('gran', 'Un llop cuiner? Això sí que no ho havia vist mai!', '¿Un lobo cocinero? ¡Eso sí que no lo había visto nunca!', 'A wolf chef? I have never seen that before!'),
        l('n', "L'àvia va obrir la porta, amb un davantal i una cullera enorme.", 'La abuela abrió la puerta, con un delantal y una cuchara enorme.', 'Grandma opened the door, with an apron and a huge spoon.', 'door'),
        l('gran', "Molt bé, llop. Renta't les mans i posa't el davantal!", 'Muy bien, lobo. ¡Lávate las manos y ponte el delantal!', 'All right, wolf. Wash your hands and put on an apron!'),
        l('wolf', 'Sí, xef! Vull dir... sí, àvia!', '¡Sí, chef! Quiero decir... ¡sí, abuela!', 'Yes, chef! I mean... yes, Grandma!'),
        l('n', "L'àvia va ensenyar al llop a tallar la carbassa a trossets.", 'La abuela enseñó al lobo a cortar la calabaza en trocitos.', 'Grandma showed the wolf how to cut the pumpkin into little pieces.'),
        l('wolf', 'Ai! Tinc les urpes massa grans per a aquest ganivet!', '¡Ay! ¡Tengo las garras demasiado grandes para este cuchillo!', 'Oops! My claws are too big for this knife!'),
        l('girl', 'No passa res! Jo t\'ajudo. Tallem-la junts.', '¡No pasa nada! Yo te ayudo. Cortémosla juntos.', "Don't worry! I'll help you. Let's cut it together."),
        l('bird', 'Piu, piu! Jo també ajudo! Porto una mica de sal!', '¡Pío, pío! ¡Yo también ayudo! ¡Traigo un poco de sal!', "Tweet, tweet! I'll help too! I've brought some salt!"),
        l('n', 'La sopa va començar a bullir: blup, blup, blup!', 'La sopa empezó a hervir: ¡blup, blup, blup!', 'The soup started to bubble: blub, blub, blub!', 'bubble'),
        l('gran', 'I ara, el secret de la recepta: una mica de canyella!', 'Y ahora, el secreto de la receta: ¡un poco de canela!', 'And now, the secret of the recipe: a little cinnamon!', 'magic'),
        l('wolf', 'Canyella a la sopa? Quina idea més boja... i genial!', '¿Canela en la sopa? ¡Qué idea tan loca... y genial!', 'Cinnamon in soup? What a crazy... and brilliant idea!'),
        l('n', 'Tots es van asseure a taula, amb una cullera cadascú.', 'Todos se sentaron a la mesa, con una cuchara cada uno.', 'They all sat at the table, each with a spoon.'),
        l('girl', 'Uau! És la sopa més bona que he tastat mai!', '¡Guau! ¡Es la sopa más rica que he probado nunca!', 'Wow! This is the best soup I have ever tasted!'),
        l('wolf', 'Àvia, ets la millor mestra de cuina del bosc!', '¡Abuela, eres la mejor maestra de cocina del bosque!', 'Grandma, you are the best cooking teacher in the forest!'),
        l('gran', 'I tu, llop, ets l\'alumne més educat que he tingut mai!', '¡Y tú, lobo, eres el alumno más educado que he tenido nunca!', 'And you, wolf, are the politest pupil I have ever had!'),
        l('bird', 'Piu... Ho sento, llop. Pensava que eres dolent.', 'Pío... Lo siento, lobo. Pensaba que eras malo.', 'Tweet... I am sorry, wolf. I thought you were bad.'),
        l('wolf', 'No passa res, ocellet. Tothom es pot equivocar.', 'No pasa nada, pajarito. Todo el mundo se puede equivocar.', "That's all right, little bird. Everyone makes mistakes."),
        l('n', "Des d'aquell dia, el llop va obrir un restaurant al bosc.", 'Desde aquel día, el lobo abrió un restaurante en el bosque.', 'From that day on, the wolf opened a restaurant in the forest.', 'ding'),
        l('wolf', 'Benvinguts a «La Sopa del Llop»! Avui, sopa de carbassa!', '¡Bienvenidos a «La Sopa del Lobo»! ¡Hoy, sopa de calabaza!', "Welcome to The Wolf's Soup! Today, pumpkin soup!"),
        l('girl', 'I la recepta secreta és de la meva àvia!', '¡Y la receta secreta es de mi abuela!', 'And the secret recipe is from my grandma!'),
        l('n', 'I conte contat, aquest conte s\'ha acabat... amb una bona sopa!', 'Y colorín colorado, este cuento se ha acabado... ¡con una buena sopa!', 'And that is the end of the story... with a lovely bowl of soup!', 'tada'),
      ],
